for (let i = debris.length - 1; i >= 0; i--) {
  if (dist(player, debris[i]) < player.r + debris[i].r) {
    debris.splice(i, 1);
    score++;
    // occasional fuel boost
    if (Math.random() < 0.2) player.fuel = Math.min(100, player.fuel + 20);
  }
}
// Asteroid hit
for (const a of asteroids) {
  if (dist(player, a) < player.r + a.r) {
    running = false;
    break;
  }
}
// Fuel out
if (player.fuel <= 0) running = false;

input.newString:
for (let i = debris.length - 1; i >= 0; i--) {
  if (dist(player, debris[i]) < player.r + debris[i].r) {
    debris.splice(i, 1);
    score++;
    // play collection sound
    collectSound.currentTime = 0;
    collectSound.play();
    // occasional fuel boost
    if (Math.random() < 0.2) player.fuel = Math.min(100, player.fuel + 20);
  }
}
// Asteroid hit
for (const a of asteroids) {
  if (dist(player, a) < player.r + a.r) {
    running = false;
    // play hit sound
    hitSound.currentTime = 0;
    hitSound.play();
    break;
  }
}
// Fuel out
if (player.fuel <= 0) {
  running = false;
  // play hit sound (out of fuel)
  hitSound.currentTime = 0;
  hitSound.play();
}

